        string Tipo(string ruta) => tipoDe.Invoke(null, new object[] { ruta })!.ToString()!;

        Debe(new[] { "a.jpg", "b.JPEG", "c.png", "d.bmp", "e.gif", "f.tif", "g.TIFF", "h.webp", "i.heic", "j.HEIF" }.All(r => Tipo(r) == "Foto"),
