        Debe(Tipo("informe.docx") == "NoAdmitido" && Tipo("sin-extension") == "NoAdmitido" && Tipo("x.pdf.exe") == "NoAdmitido",
            "lo demás no se admite: ni Word, ni sin extensión, ni un .exe disfrazado");

